// constat:template id=jest-coverage version=52 sha256=ddd45147a174bee80148851d68d31893a96d3ec6971217bb0d29c984e4162aa3
// Generated by DoneMark's onboarding pull request. Produces the "constat-check-coverage"
// workflow artifact: for every test file jest runs, which lines of which source files it was
// observed executing, AND — for every test file this run could not measure at all — its own name
// alongside the failure's own words. This is what lets DoneMark tell a check that runs the lines a
// change added apart from one that merely sits beside them, and tell "CI tried to measure this and
// failed" apart from "this check's file was never in the report" at all. Best-effort by design:
// one test file's coverage run failing does not stop the rest — it is logged AND named in the
// report's own `unmeasured` manifest, never fatal to the whole job and never silently dropped.
//
// Usage: node .github/scripts/constat-jest-coverage.mjs <outputFile>

import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative } from 'node:path';

const [, , outputFile] = process.argv;
if (!outputFile) {
  console.error('usage: constat-jest-coverage.mjs <outputFile>');
  process.exit(2);
}

const repoRoot = process.cwd();
// Bounds one CI job's runtime: each test file is one extra jest process. Above this, coverage
// degrades to "not published for the rest" rather than let one repo's test count run the job for
// an hour. Every file dropped by the cap is named in the job log — never a silent truncation.
const FILE_CAP = 300;

let testFiles;
try {
  const listed = execFileSync('npx', ['jest', '--listTests'], { encoding: 'utf8', cwd: repoRoot });
  testFiles = listed.split('\n').map((l) => l.trim()).filter(Boolean);
} catch (err) {
  console.error(`could not list jest's own test files: ${err.message.split('\n')[0]}`);
  process.exit(1);
}
testFiles.sort();
const capped = testFiles.length > FILE_CAP;
const inScope = capped ? testFiles.slice(0, FILE_CAP) : testFiles;

const files = {};
// Repo-relative test file -> the failure's own words for why this run could not measure it.
// Never holds an entry for a file whose run simply SUCCEEDED and executed nothing — that is a
// real measurement ("this check touches nothing"), not an absence, and belongs in `files`.
const unmeasured = {};
if (capped) {
  const overflow = testFiles.slice(FILE_CAP);
  console.warn(
    `::warning::${testFiles.length} test files found, coverage capped at ${FILE_CAP} — ` +
      `${overflow.length} file(s) will publish no coverage entry this run.`,
  );
  for (const testFile of overflow) {
    unmeasured[relative(repoRoot, testFile)] = `coverage capped at ${FILE_CAP} test files — this run did not attempt it`;
  }
}

for (const testFile of inScope) {
  const testRel = relative(repoRoot, testFile);
  const outDir = mkdtempSync(join(tmpdir(), 'constat-cov-'));
  try {
    execFileSync(
      'npx',
      [
        'jest', testFile, '--coverage', '--coverageProvider=v8',
        '--coverageReporters=json', `--coverageDirectory=${outDir}`,
      ],
      { cwd: repoRoot, stdio: ['ignore', 'ignore', 'pipe'], timeout: 120_000 },
    );
  } catch (err) {
    const reason = `coverage run failed: ${String(err.message).split('\n')[0]}`;
    console.warn(`::warning::${reason} — ${testRel}`);
    unmeasured[testRel] = reason;
    rmSync(outDir, { recursive: true, force: true });
    continue;
  }
  const reportPath = join(outDir, 'coverage-final.json');
  if (!existsSync(reportPath)) {
    const reason = 'coverage run produced no coverage-final.json';
    console.warn(`::warning::${reason} — ${testRel}`);
    unmeasured[testRel] = reason;
    rmSync(outDir, { recursive: true, force: true });
    continue;
  }
  const report = JSON.parse(readFileSync(reportPath, 'utf8'));
  const perSource = {};
  for (const [absPath, entry] of Object.entries(report)) {
    const sourceRel = relative(repoRoot, absPath);
    // Never the test file crediting itself with "coverage" of its own assertions — only the
    // PRODUCTION lines a check exercises answer "does this check touch the change".
    if (sourceRel === testRel) continue;
    if (sourceRel.startsWith('..')) continue; // outside the repo entirely
    const lines = new Set();
    for (const [stmtId, hits] of Object.entries(entry.s ?? {})) {
      if (hits <= 0) continue;
      const range = entry.statementMap?.[stmtId];
      if (!range) continue;
      for (let line = range.start.line; line <= range.end.line; line += 1) lines.add(line);
    }
    if (lines.size > 0) perSource[sourceRel] = [...lines].sort((a, b) => a - b);
  }
  // Written even when perSource is empty: a coverage run that completed and genuinely executed no
  // source line (the shape a text-level component test takes when a repository has no rendering
  // harness — asserting against the source as read text rather than importing and running it) is
  // a real measurement, not an absence, and must be told apart from a file the report never
  // mentions at all. See @constat/evidence's compareCoverage.
  files[testRel] = perSource;
  rmSync(outDir, { recursive: true, force: true });
}

mkdirSync(dirname(outputFile), { recursive: true });
writeFileSync(outputFile, `${JSON.stringify({ schema: 'constat.check-coverage/v1', files, unmeasured }, null, 2)}\n`);
console.log(
  `wrote coverage for ${Object.keys(files).length} test file(s) (${Object.keys(unmeasured).length} unmeasured) to ${outputFile}`,
);
